    pub fn batchNorm(self: *Tensor, allocator: Allocator, gamma: *const Tensor, beta: *const Tensor, eps: f32, training: bool) !struct { normalized: Tensor, mean: ?Tensor, variance: ?Tensor } {
        if (self.shape.dims.len < 2) return Error.InvalidShape;
        const batch_size = self.shape.dims[0];
        const feature_dim = self.shape.dims[self.shape.dims.len - 1];

        if (training) {
            var mean_t = try self.mean(allocator, 0);
            var variance_t = try self.variance(allocator, 0);
            var normalized = try self.copy(allocator);

            var mean_broadcasted = try mean_t.unsqueeze(allocator, 0);
            defer mean_broadcasted.deinit();
            var mean_full = try mean_broadcasted.broadcast(self.shape.dims);
            defer mean_full.deinit();

            try normalized.sub(&mean_full);

            var var_broadcasted = try variance_t.unsqueeze(allocator, 0);
            defer var_broadcasted.deinit();
            var var_full = try var_broadcasted.broadcast(self.shape.dims);
            defer var_full.deinit();

            var i: usize = 0;
            while (i < normalized.data.len) : (i += 1) {
                normalized.data[i] /= @sqrt(var_full.data[i] + eps);
            }

            var gamma_broadcasted = try gamma.unsqueeze(allocator, 0);
            defer gamma_broadcasted.deinit();
            var gamma_full = try gamma_broadcasted.broadcast(self.shape.dims);
            defer gamma_full.deinit();

            try normalized.mul(&gamma_full);

            var beta_broadcasted = try beta.unsqueeze(allocator, 0);
            defer beta_broadcasted.deinit();
            var beta_full = try beta_broadcasted.broadcast(self.shape.dims);
            defer beta_full.deinit();

            try normalized.add(&beta_full);

            return .{ .normalized = normalized, .mean = mean_t, .variance = variance_t };
        } else {
            var normalized = try self.copy(allocator);
            var i: usize = 0;
            while (i < normalized.data.len) : (i += 1) {
                const feat_idx = i % feature_dim;
                normalized.data[i] = (normalized.data[i] - 0.0) / @sqrt(1.0 + eps);
                normalized.data[i] = normalized.data[i] * gamma.data[feat_idx] + beta.data[feat_idx];
            }
            return .{ .normalized = normalized, .mean = null, .variance = null };
        }
    }

    pub fn layerNorm(self: *Tensor, allocator: Allocator, normalized_shape: []const usize, gamma: *const Tensor, beta: *const Tensor, eps: f32) !Tensor {
        const last_dims = self.shape.dims.len - normalized_shape.len;
        var axes = try allocator.alloc(usize, normalized_shape.len);
        defer allocator.free(axes);
        var i: usize = 0;
        while (i < normalized_shape.len) : (i += 1) {
            axes[i] = last_dims + i;
        }

        var mean_val: f32 = 0.0;
        for (self.data) |val| mean_val += val;
        mean_val /= @as(f32, @floatFromInt(self.data.len));

        var variance_val: f32 = 0.0;
        for (self.data) |val| {
            const diff = val - mean_val;
            variance_val += diff * diff;
        }
        variance_val /= @as(f32, @floatFromInt(self.data.len));

        var normalized = try self.copy(allocator);
        for (normalized.data) |*val| {
            val.* = (val.* - mean_val) / @sqrt(variance_val + eps);
        }

        try normalized.mul(gamma);
        try normalized.add(beta);

        return normalized;
    }

    pub fn groupNorm(self: *Tensor, allocator: Allocator, num_groups: usize, gamma: *const Tensor, beta: *const Tensor, eps: f32) !Tensor {
        if (self.shape.dims.len < 3) return Error.InvalidShape;
        const batch_size = self.shape.dims[0];
        const num_channels = self.shape.dims[1];
        if (num_channels % num_groups != 0) return Error.InvalidShape;

        const channels_per_group = num_channels / num_groups;
        var normalized = try self.copy(allocator);

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            var g: usize = 0;
            while (g < num_groups) : (g += 1) {
                var sum: f32 = 0.0;
                var count: usize = 0;

                var c: usize = g * channels_per_group;
                while (c < (g + 1) * channels_per_group) : (c += 1) {
                    var spatial: usize = 0;
                    const spatial_size = self.data.len / (batch_size * num_channels);
                    while (spatial < spatial_size) : (spatial += 1) {
                        const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                        sum += self.data[idx];
                        count += 1;
                    }
                }

                const mean_val = sum / @as(f32, @floatFromInt(count));

                var variance: f32 = 0.0;
                c = g * channels_per_group;
                while (c < (g + 1) * channels_per_group) : (c += 1) {
                    var spatial: usize = 0;
                    const spatial_size = self.data.len / (batch_size * num_channels);
                    while (spatial < spatial_size) : (spatial += 1) {
                        const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                        const diff = self.data[idx] - mean_val;
                        variance += diff * diff;
                    }
                }
                variance /= @as(f32, @floatFromInt(count));

                c = g * channels_per_group;
                while (c < (g + 1) * channels_per_group) : (c += 1) {
                    var spatial: usize = 0;
                    const spatial_size = self.data.len / (batch_size * num_channels);
                    while (spatial < spatial_size) : (spatial += 1) {
                        const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                        normalized.data[idx] = (normalized.data[idx] - mean_val) / @sqrt(variance + eps);
                        normalized.data[idx] = normalized.data[idx] * gamma.data[c] + beta.data[c];
                    }
                }
            }
        }

        return normalized;
    }

    pub fn instanceNorm(self: *Tensor, allocator: Allocator, gamma: *const Tensor, beta: *const Tensor, eps: f32) !Tensor {
        if (self.shape.dims.len < 3) return Error.InvalidShape;
        const batch_size = self.shape.dims[0];
        const num_channels = self.shape.dims[1];
        const spatial_size = self.data.len / (batch_size * num_channels);

        var normalized = try self.copy(allocator);

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            var c: usize = 0;
            while (c < num_channels) : (c += 1) {
                var sum: f32 = 0.0;
                var spatial: usize = 0;
                while (spatial < spatial_size) : (spatial += 1) {
                    const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                    sum += self.data[idx];
                }
                const mean_val = sum / @as(f32, @floatFromInt(spatial_size));

                var variance: f32 = 0.0;
                spatial = 0;
                while (spatial < spatial_size) : (spatial += 1) {
                    const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                    const diff = self.data[idx] - mean_val;
                    variance += diff * diff;
                }
                variance /= @as(f32, @floatFromInt(spatial_size));

                spatial = 0;
                while (spatial < spatial_size) : (spatial += 1) {
                    const idx = b * num_channels * spatial_size + c * spatial_size + spatial;
                    normalized.data[idx] = (normalized.data[idx] - mean_val) / @sqrt(variance + eps);
                    normalized.data[idx] = normalized.data[idx] * gamma.data[c] + beta.data[c];
                }
            }
        }

        return normalized;
    }

    pub fn dropout(self: *Tensor, allocator: Allocator, p: f32, training: bool, seed: u64) !Tensor {
        if (!training) return try self.copy(allocator);

        var prng = types.PRNG.init(seed);
        var result = try self.copy(allocator);
        const scale = 1.0 / (1.0 - p);

        for (result.data) |*val| {
            const rand_val = prng.float();
            if (rand_val < p) {
                val.* = 0.0;
            } else {
                val.* *= scale;
            }
        }

        return result;
    }

    pub fn alphaDropout(self: *Tensor, allocator: Allocator, p: f32, training: bool, seed: u64) !Tensor {
        if (!training) return try self.copy(allocator);

        const alpha: f32 = 1.6732632423543772;
        const scale: f32 = 1.0507009873554805;
        const alpha_p = -alpha * scale;

        const a = @sqrt((1.0 - p) * (1.0 + p * alpha_p * alpha_p));
        const b = -a * alpha_p * p;

        var prng = types.PRNG.init(seed);
        var result = try self.copy(allocator);

        for (result.data) |*val| {
            const rand_val = prng.float();
            if (rand_val < p) {
                val.* = alpha_p;
            }
            val.* = a * val.* + b;
        }

        return result;
    }

    pub fn leakyReLU(self: *Tensor, negative_slope: f32) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            if (val.* < 0.0) {
                val.* *= negative_slope;
            }
        }
    }

    pub fn elu(self: *Tensor, alpha: f32) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            if (val.* < 0.0) {
                val.* = alpha * (@exp(val.*) - 1.0);
            }
        }
    }

    pub fn selu(self: *Tensor) !void {
        try ensureWritable(self);
        const alpha: f32 = 1.6732632423543772;
        const scale: f32 = 1.0507009873554805;
        for (self.data) |*val| {
            if (val.* > 0.0) {
                val.* = scale * val.*;
            } else {
                val.* = scale * alpha * (@exp(val.*) - 1.0);
            }
        }
    }

    pub fn gelu(self: *Tensor) !void {
        try ensureWritable(self);
        const sqrt_2_over_pi: f32 = 0.7978845608;
        for (self.data) |*val| {
            const x = val.*;
            const cdf = 0.5 * (1.0 + @tanh(sqrt_2_over_pi * (x + 0.044715 * x * x * x)));
            val.* = x * cdf;
        }
    }

    pub fn swish(self: *Tensor) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            val.* = val.* / (1.0 + @exp(-val.*));
        }
    }

    pub fn mish(self: *Tensor) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            val.* = val.* * @tanh(@log(1.0 + @exp(val.*)));
        }
    }

    pub fn hardSwish(self: *Tensor) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            if (val.* <= -3.0) {
                val.* = 0.0;
            } else if (val.* >= 3.0) {
                val.* = val.*;
            } else {
                val.* = val.* * (val.* + 3.0) / 6.0;
            }
        }
    }

    pub fn hardSigmoid(self: *Tensor) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            val.* = math.clamp((val.* + 3.0) / 6.0, 0.0, 1.0);
        }
    }

    pub fn prelu(self: *Tensor, alpha: *const Tensor) !void {
        if (alpha.data.len != 1 and alpha.data.len != self.data.len) return Error.ShapeMismatch;
        try ensureWritable(self);

        if (alpha.data.len == 1) {
            const a = alpha.data[0];
            for (self.data) |*val| {
                if (val.* < 0.0) val.* *= a;
            }
        } else {
            var i: usize = 0;
            while (i < self.data.len) : (i += 1) {
                if (self.data[i] < 0.0) self.data[i] *= alpha.data[i];
            }
        }
    }

    pub fn rrelu(self: *Tensor, lower: f32, upper: f32, training: bool, seed: u64) !void {
        try ensureWritable(self);
        if (training) {
            var prng = types.PRNG.init(seed);
            for (self.data) |*val| {
                if (val.* < 0.0) {
                    const a = lower + prng.float() * (upper - lower);
                    val.* *= a;
                }
            }
        } else {
            const a = (lower + upper) / 2.0;
            for (self.data) |*val| {
                if (val.* < 0.0) val.* *= a;
            }
        }
    }

    pub fn celu(self: *Tensor, alpha: f32) !void {
        try ensureWritable(self);
        for (self.data) |*val| {
            val.* = @max(0.0, val.*) + @min(0.0, alpha * (@exp(val.* / alpha) - 1.0));
        }
    }

    pub fn glu(self: *Tensor, allocator: Allocator, dim: usize) !Tensor {
        if (dim >= self.shape.dims.len) return Error.InvalidAxis;
        if (self.shape.dims[dim] % 2 != 0) return Error.InvalidShape;

        const split_size = self.shape.dims[dim] / 2;
        var new_shape = try allocator.alloc(usize, self.shape.dims.len);
        defer allocator.free(new_shape);
        @memcpy(new_shape, self.shape.dims);
        new_shape[dim] = split_size;

        var a = try init(allocator, new_shape);
        var b = try init(allocator, new_shape);

        var idx: usize = 0;
        while (idx < self.data.len) : (idx += 1) {
            const dim_idx = (idx / self.shape.strides[dim]) % self.shape.dims[dim];
            if (dim_idx < split_size) {
                const out_idx = idx - (dim_idx) * self.shape.strides[dim] + dim_idx * (self.shape.strides[dim] / 2);
                if (out_idx < a.data.len) a.data[out_idx] = self.data[idx];
            } else {
                const out_idx = idx - split_size * self.shape.strides[dim] - (dim_idx - split_size) * self.shape.strides[dim] + (dim_idx - split_size) * (self.shape.strides[dim] / 2);
                if (out_idx < b.data.len) b.data[out_idx] = self.data[idx];
            }
        }

        for (b.data) |*val| {
            val.* = 1.0 / (1.0 + @exp(-val.*));
        }

        try a.mul(&b);
        b.deinit();
        return a;
    }

    pub fn attention(query: *const Tensor, key: *const Tensor, value: *const Tensor, allocator: Allocator, mask: ?*const Tensor, dropout_p: f32, training: bool, seed: u64) !Tensor {
        if (query.shape.dims.len < 3 or key.shape.dims.len < 3 or value.shape.dims.len < 3) return Error.InvalidShape;

        const d_k = @as(f32, @floatFromInt(key.shape.dims[key.shape.dims.len - 1]));

        var key_transposed = try key.transpose(&.{ 0, 2, 1 });
        defer key_transposed.deinit();

        var scores = try matmul(query, &key_transposed, allocator);
        try scores.divScalar(@sqrt(d_k));

        if (mask) |m| {
            var i: usize = 0;
            while (i < scores.data.len) : (i += 1) {
                if (m.data[i % m.data.len] == 0.0) {
                    scores.data[i] = -1e9;
                }
            }
        }

        const last_dim = scores.shape.dims.len - 1;
        try scores.softmax(last_dim);

        if (training and dropout_p > 0.0) {
            var scores_dropped = try scores.dropout(allocator, dropout_p, true, seed);
            scores.deinit();
            scores = scores_dropped;
        }

        var output = try matmul(&scores, value, allocator);
        scores.deinit();
        return output;
    }

    pub fn multiheadAttention(query: *const Tensor, key: *const Tensor, value: *const Tensor, allocator: Allocator, num_heads: usize, embed_dim: usize, mask: ?*const Tensor, dropout_p: f32, training: bool, seed: u64) !Tensor {
        if (embed_dim % num_heads != 0) return Error.InvalidShape;

        const head_dim = embed_dim / num_heads;
        const batch_size = query.shape.dims[0];
        const seq_len = query.shape.dims[1];

        var all_head_outputs = std.ArrayList(Tensor).init(allocator);
        defer {
            for (all_head_outputs.items) |*t| t.deinit();
            all_head_outputs.deinit();
        }

        var h: usize = 0;
        while (h < num_heads) : (h += 1) {
            const start_idx = h * head_dim;
            const end_idx = (h + 1) * head_dim;

            var q_head = try query.slice(&.{ 0, 0, start_idx }, &.{ batch_size, seq_len, end_idx });
            defer q_head.deinit();
            var k_head = try key.slice(&.{ 0, 0, start_idx }, &.{ batch_size, seq_len, end_idx });
            defer k_head.deinit();
            var v_head = try value.slice(&.{ 0, 0, start_idx }, &.{ batch_size, seq_len, end_idx });
            defer v_head.deinit();

            var head_out = try attention(&q_head, &k_head, &v_head, allocator, mask, dropout_p, training, seed + h);
            try all_head_outputs.append(head_out);
        }

        return try concat(allocator, all_head_outputs.items, 2);
    }

    pub fn conv1d(self: *const Tensor, kernel: *const Tensor, allocator: Allocator, stride: usize, padding: usize, dilation: usize) !Tensor {
        if (self.shape.dims.len != 3 or kernel.shape.dims.len != 3) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_length = self.shape.dims[1];
        const in_channels = self.shape.dims[2];
        const kernel_size = kernel.shape.dims[0];
        const out_channels = kernel.shape.dims[2];

        const out_length = ((in_length + 2 * padding - dilation * (kernel_size - 1) - 1) / stride) + 1;

        const output = try init(allocator, &.{ batch, out_length, out_channels });

        var padded_input = if (padding > 0) 
            try self.pad(allocator, &.{ .{0, 0}, .{padding, padding}, .{0, 0} })
        else 
            try self.copy(allocator);
        defer if (padding > 0) padded_input.deinit() else padded_input.deinit();

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var o: usize = 0;
            while (o < out_length) : (o += 1) {
                var oc: usize = 0;
                while (oc < out_channels) : (oc += 1) {
                    var sum: f32 = 0.0;
                    var k: usize = 0;
                    while (k < kernel_size) : (k += 1) {
                        var ic: usize = 0;
                        while (ic < in_channels) : (ic += 1) {
                            const in_idx = o * stride + k * dilation;
                            if (in_idx < padded_input.shape.dims[1]) {
                                sum += try padded_input.get(&.{ b, in_idx, ic }) * try kernel.get(&.{ k, ic, oc });
                            }
                        }
                    }
                    try output.set(&.{ b, o, oc }, sum);
                }
            }
        }

        return output;
    }

    pub fn conv3d(self: *const Tensor, kernel: *const Tensor, allocator: Allocator, stride: [3]usize, padding: [3]usize) !Tensor {
        if (self.shape.dims.len != 5 or kernel.shape.dims.len != 5) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_d = self.shape.dims[1];
        const in_h = self.shape.dims[2];
        const in_w = self.shape.dims[3];
        const in_c = self.shape.dims[4];

        const k_d = kernel.shape.dims[0];
        const k_h = kernel.shape.dims[1];
        const k_w = kernel.shape.dims[2];
        const out_c = kernel.shape.dims[4];

        const out_d = ((in_d + 2 * padding[0] - k_d) / stride[0]) + 1;
        const out_h = ((in_h + 2 * padding[1] - k_h) / stride[1]) + 1;
        const out_w = ((in_w + 2 * padding[2] - k_w) / stride[2]) + 1;

        const output = try init(allocator, &.{ batch, out_d, out_h, out_w, out_c });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var od: usize = 0;
            while (od < out_d) : (od += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var oc: usize = 0;
                        while (oc < out_c) : (oc += 1) {
                            var sum: f32 = 0.0;
                            var kd: usize = 0;
                            while (kd < k_d) : (kd += 1) {
                                var kh: usize = 0;
                                while (kh < k_h) : (kh += 1) {
                                    var kw: usize = 0;
                                    while (kw < k_w) : (kw += 1) {
                                        var ic: usize = 0;
                                        while (ic < in_c) : (ic += 1) {
                                            const id = od * stride[0] + kd;
                                            const ih = oh * stride[1] + kh;
                                            const iw = ow * stride[2] + kw;

                                            if (id >= padding[0] and id < in_d + padding[0] and
                                                ih >= padding[1] and ih < in_h + padding[1] and
                                                iw >= padding[2] and iw < in_w + padding[2]) {
                                                const actual_id = id - padding[0];
                                                const actual_ih = ih - padding[1];
                                                const actual_iw = iw - padding[2];
                                                sum += try self.get(&.{ b, actual_id, actual_ih, actual_iw, ic }) * try kernel.get(&.{ kd, kh, kw, ic, oc });
                                            }
                                        }
                                    }
                                }
                            }
                            try output.set(&.{ b, od, oh, ow, oc }, sum);
                        }
                    }
                }
            }
        }

        return output;
    }

    pub fn depthwiseConv2d(self: *const Tensor, kernel: *const Tensor, allocator: Allocator, stride: [2]usize, padding: [2]usize) !Tensor {
        if (self.shape.dims.len != 4 or kernel.shape.dims.len != 4) return Error.InvalidShape;
        if (self.shape.dims[3] != kernel.shape.dims[2]) return Error.ShapeMismatch;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];
        const k_h = kernel.shape.dims[0];
        const k_w = kernel.shape.dims[1];

        const out_h = ((in_h + 2 * padding[0] - k_h) / stride[0]) + 1;
        const out_w = ((in_w + 2 * padding[1] - k_w) / stride[1]) + 1;

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var c: usize = 0;
            while (c < channels) : (c += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var sum: f32 = 0.0;
                        var kh: usize = 0;
                        while (kh < k_h) : (kh += 1) {
                            var kw: usize = 0;
                            while (kw < k_w) : (kw += 1) {
                                const ih = oh * stride[0] + kh;
                                const iw = ow * stride[1] + kw;

                                if (ih >= padding[0] and ih < in_h + padding[0] and
                                    iw >= padding[1] and iw < in_w + padding[1]) {
                                    const actual_ih = ih - padding[0];
                                    const actual_iw = iw - padding[1];
                                    sum += try self.get(&.{ b, actual_ih, actual_iw, c }) * try kernel.get(&.{ kh, kw, c, 0 });
                                }
                            }
                        }
                        try output.set(&.{ b, oh, ow, c }, sum);
                    }
                }
            }
        }

        return output;
    }

    pub fn separableConv2d(self: *const Tensor, depthwise_kernel: *const Tensor, pointwise_kernel: *const Tensor, allocator: Allocator, stride: [2]usize, padding: [2]usize) !Tensor {
        var depthwise_out = try self.depthwiseConv2d(depthwise_kernel, allocator, stride, padding);
        defer depthwise_out.deinit();

        return try depthwise_out.conv2d(pointwise_kernel, allocator, .{ 1, 1 }, .{ 0, 0 });
    }

    pub fn transposedConv2d(self: *const Tensor, kernel: *const Tensor, allocator: Allocator, stride: [2]usize, padding: [2]usize, output_padding: [2]usize) !Tensor {
        if (self.shape.dims.len != 4 or kernel.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const in_c = self.shape.dims[3];
        const k_h = kernel.shape.dims[0];
        const k_w = kernel.shape.dims[1];
        const out_c = kernel.shape.dims[3];

        const out_h = (in_h - 1) * stride[0] - 2 * padding[0] + k_h + output_padding[0];
        const out_w = (in_w - 1) * stride[1] - 2 * padding[1] + k_w + output_padding[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, out_c });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var ih: usize = 0;
            while (ih < in_h) : (ih += 1) {
                var iw: usize = 0;
                while (iw < in_w) : (iw += 1) {
                    var ic: usize = 0;
                    while (ic < in_c) : (ic += 1) {
                        const in_val = try self.get(&.{ b, ih, iw, ic });
                        var kh: usize = 0;
                        while (kh < k_h) : (kh += 1) {
                            var kw: usize = 0;
                            while (kw < k_w) : (kw += 1) {
                                var oc: usize = 0;
                                while (oc < out_c) : (oc += 1) {
                                    const oh = ih * stride[0] + kh - padding[0];
                                    const ow = iw * stride[1] + kw - padding[1];

                                    if (oh < out_h and ow < out_w) {
                                        const kernel_val = try kernel.get(&.{ kh, kw, ic, oc });
                                        const current_val = try output.get(&.{ b, oh, ow, oc });
                                        try output.set(&.{ b, oh, ow, oc }, current_val + in_val * kernel_val);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        return output;
    }

    pub fn dilatedConv2d(self: *const Tensor, kernel: *const Tensor, allocator: Allocator, stride: [2]usize, padding: [2]usize, dilation: [2]usize) !Tensor {
        if (self.shape.dims.len != 4 or kernel.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const in_c = self.shape.dims[3];
        const k_h = kernel.shape.dims[0];
        const k_w = kernel.shape.dims[1];
        const out_c = kernel.shape.dims[3];

        const effective_k_h = k_h + (k_h - 1) * (dilation[0] - 1);
        const effective_k_w = k_w + (k_w - 1) * (dilation[1] - 1);
        const out_h = ((in_h + 2 * padding[0] - effective_k_h) / stride[0]) + 1;
        const out_w = ((in_w + 2 * padding[1] - effective_k_w) / stride[1]) + 1;

        const output = try init(allocator, &.{ batch, out_h, out_w, out_c });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    var oc: usize = 0;
                    while (oc < out_c) : (oc += 1) {
                        var sum: f32 = 0.0;
                        var kh: usize = 0;
                        while (kh < k_h) : (kh += 1) {
                            var kw: usize = 0;
                            while (kw < k_w) : (kw += 1) {
                                var ic: usize = 0;
                                while (ic < in_c) : (ic += 1) {
                                    const ih = oh * stride[0] + kh * dilation[0];
                                    const iw = ow * stride[1] + kw * dilation[1];

                                    if (ih >= padding[0] and ih < in_h + padding[0] and
                                        iw >= padding[1] and iw < in_w + padding[1]) {
                                        const actual_ih = ih - padding[0];
                                        const actual_iw = iw - padding[1];
                                        sum += try self.get(&.{ b, actual_ih, actual_iw, ic }) * try kernel.get(&.{ kh, kw, ic, oc });
                                    }
                                }
                            }
                        }
                        try output.set(&.{ b, oh, ow, oc }, sum);
                    }
                }
            }
        }

        return output;
    }

    pub fn maxPool1d(self: *const Tensor, allocator: Allocator, kernel_size: usize, stride: usize, padding: usize) !Tensor {
        if (self.shape.dims.len != 3) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_length = self.shape.dims[1];
        const channels = self.shape.dims[2];

        const out_length = ((in_length + 2 * padding - kernel_size) / stride) + 1;
        const output = try init(allocator, &.{ batch, out_length, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var o: usize = 0;
            while (o < out_length) : (o += 1) {
                var c: usize = 0;
                while (c < channels) : (c += 1) {
                    var max_val: f32 = -math.inf(f32);
                    var k: usize = 0;
                    while (k < kernel_size) : (k += 1) {
                        const idx = o * stride + k;
                        if (idx >= padding and idx < in_length + padding) {
                            const actual_idx = idx - padding;
                            const val = try self.get(&.{ b, actual_idx, c });
                            if (val > max_val) max_val = val;
                        }
                    }
                    try output.set(&.{ b, o, c }, max_val);
                }
            }
        }

        return output;
    }

    pub fn avgPool1d(self: *const Tensor, allocator: Allocator, kernel_size: usize, stride: usize, padding: usize) !Tensor {
        if (self.shape.dims.len != 3) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_length = self.shape.dims[1];
        const channels = self.shape.dims[2];

        const out_length = ((in_length + 2 * padding - kernel_size) / stride) + 1;
        const output = try init(allocator, &.{ batch, out_length, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var o: usize = 0;
            while (o < out_length) : (o += 1) {
                var c: usize = 0;
                while (c < channels) : (c += 1) {
                    var sum: f32 = 0.0;
                    var count: usize = 0;
                    var k: usize = 0;
                    while (k < kernel_size) : (k += 1) {
                        const idx = o * stride + k;
                        if (idx >= padding and idx < in_length + padding) {
                            const actual_idx = idx - padding;
                            sum += try self.get(&.{ b, actual_idx, c });
                            count += 1;
                        }
                    }
                    try output.set(&.{ b, o, c }, sum / @as(f32, @floatFromInt(count)));
                }
            }
        }

        return output;
    }

    pub fn maxPool3d(self: *const Tensor, allocator: Allocator, kernel_size: [3]usize, stride: [3]usize, padding: [3]usize) !Tensor {
        if (self.shape.dims.len != 5) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_d = self.shape.dims[1];
        const in_h = self.shape.dims[2];
        const in_w = self.shape.dims[3];
        const channels = self.shape.dims[4];

        const out_d = ((in_d + 2 * padding[0] - kernel_size[0]) / stride[0]) + 1;
        const out_h = ((in_h + 2 * padding[1] - kernel_size[1]) / stride[1]) + 1;
        const out_w = ((in_w + 2 * padding[2] - kernel_size[2]) / stride[2]) + 1;

        const output = try init(allocator, &.{ batch, out_d, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var od: usize = 0;
            while (od < out_d) : (od += 1) {
                var oh: usize = 0;
                while (oh < out_h) : (oh += 1) {
                    var ow: usize = 0;
                    while (ow < out_w) : (ow += 1) {
                        var c: usize = 0;
                        while (c < channels) : (c += 1) {
                            var max_val: f32 = -math.inf(f32);
                            var kd: usize = 0;
                            while (kd < kernel_size[0]) : (kd += 1) {
                                var kh: usize = 0;
                                while (kh < kernel_size[1]) : (kh += 1) {
                                    var kw: usize = 0;
                                    while (kw < kernel_size[2]) : (kw += 1) {
                                        const id = od * stride[0] + kd;
                                        const ih = oh * stride[1] + kh;
                                        const iw = ow * stride[2] + kw;

                                        if (id >= padding[0] and id < in_d + padding[0] and
                                            ih >= padding[1] and ih < in_h + padding[1] and
                                            iw >= padding[2] and iw < in_w + padding[2]) {
                                            const actual_id = id - padding[0];
                                            const actual_ih = ih - padding[1];
                                            const actual_iw = iw - padding[2];
                                            const val = try self.get(&.{ b, actual_id, actual_ih, actual_iw, c });
                                            if (val > max_val) max_val = val;
                                        }
                                    }
                                }
                            }
                            try output.set(&.{ b, od, oh, ow, c }, max_val);
                        }
                    }
                }
            }
        }

        return output;
    }

    pub fn adaptiveAvgPool2d(self: *const Tensor, allocator: Allocator, output_size: [2]usize) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        const out_h = output_size[0];
        const out_w = output_size[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        const h_start = (oh * in_h) / out_h;
                        const h_end = ((oh + 1) * in_h) / out_h;
                        const w_start = (ow * in_w) / out_w;
                        const w_end = ((ow + 1) * in_w) / out_w;

                        var sum: f32 = 0.0;
                        var count: usize = 0;
                        var ih = h_start;
                        while (ih < h_end) : (ih += 1) {
                            var iw = w_start;
                            while (iw < w_end) : (iw += 1) {
                                sum += try self.get(&.{ b, ih, iw, c });
                                count += 1;
                            }
                        }
                        try output.set(&.{ b, oh, ow, c }, sum / @as(f32, @floatFromInt(count)));
                    }
                }
            }
        }

        return output;
    }

    pub fn adaptiveMaxPool2d(self: *const Tensor, allocator: Allocator, output_size: [2]usize) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        const out_h = output_size[0];
        const out_w = output_size[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        const h_start = (oh * in_h) / out_h;
                        const h_end = ((oh + 1) * in_h) / out_h;
                        const w_start = (ow * in_w) / out_w;
                        const w_end = ((ow + 1) * in_w) / out_w;

                        var max_val: f32 = -math.inf(f32);
                        var ih = h_start;
                        while (ih < h_end) : (ih += 1) {
                            var iw = w_start;
                            while (iw < w_end) : (iw += 1) {
                                const val = try self.get(&.{ b, ih, iw, c });
                                if (val > max_val) max_val = val;
                            }
                        }
                        try output.set(&.{ b, oh, ow, c }, max_val);
                    }
                }
            }
        }

        return output;
    }

    pub fn fractionalMaxPool2d(self: *const Tensor, allocator: Allocator, kernel_size: [2]usize, output_size: [2]usize, seed: u64) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        var prng = types.PRNG.init(seed);

        const out_h = output_size[0];
        const out_w = output_size[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var row_positions = try allocator.alloc(usize, out_h + 1);
        defer allocator.free(row_positions);
        var col_positions = try allocator.alloc(usize, out_w + 1);
        defer allocator.free(col_positions);

        row_positions[0] = 0;
        row_positions[out_h] = in_h;
        var i: usize = 1;
        while (i < out_h) : (i += 1) {
            const min_pos = (i * in_h) / out_h;
            const max_pos = ((i + 1) * in_h) / out_h;
            row_positions[i] = min_pos + @as(usize, @intFromFloat(prng.float() * @as(f32, @floatFromInt(max_pos - min_pos))));
        }

        col_positions[0] = 0;
        col_positions[out_w] = in_w;
        i = 1;
        while (i < out_w) : (i += 1) {
            const min_pos = (i * in_w) / out_w;
            const max_pos = ((i + 1) * in_w) / out_w;
            col_positions[i] = min_pos + @as(usize, @intFromFloat(prng.float() * @as(f32, @floatFromInt(max_pos - min_pos))));
        }

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        var max_val: f32 = -math.inf(f32);
                        var ih = row_positions[oh];
                        while (ih < row_positions[oh + 1]) : (ih += 1) {
                            var iw = col_positions[ow];
                            while (iw < col_positions[ow + 1]) : (iw += 1) {
                                const val = try self.get(&.{ b, ih, iw, c });
                                if (val > max_val) max_val = val;
                            }
                        }
                        try output.set(&.{ b, oh, ow, c }, max_val);
                    }
                }
            }
        }

        return output;
    }

    pub fn lpPool2d(self: *const Tensor, allocator: Allocator, norm_type: f32, kernel_size: [2]usize, stride: [2]usize) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        const out_h = ((in_h - kernel_size[0]) / stride[0]) + 1;
        const out_w = ((in_w - kernel_size[1]) / stride[1]) + 1;

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        var sum: f32 = 0.0;
                        var kh: usize = 0;
                        while (kh < kernel_size[0]) : (kh += 1) {
                            var kw: usize = 0;
                            while (kw < kernel_size[1]) : (kw += 1) {
                                const ih = oh * stride[0] + kh;
                                const iw = ow * stride[1] + kw;
                                const val = try self.get(&.{ b, ih, iw, c });
                                sum += math.pow(f32, @fabs(val), norm_type);
                            }
                        }
                        const result = math.pow(f32, sum, 1.0 / norm_type);
                        try output.set(&.{ b, oh, ow, c }, result);
                    }
                }
            }
        }

        return output;
    }

    pub fn roiAlign(self: *const Tensor, allocator: Allocator, boxes: *const Tensor, output_size: [2]usize, spatial_scale: f32, sampling_ratio: isize) !Tensor {
        if (self.shape.dims.len != 4 or boxes.shape.dims.len != 2) return Error.InvalidShape;
        if (boxes.shape.dims[1] != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const channels = self.shape.dims[3];
        const num_rois = boxes.shape.dims[0];

        const output = try init(allocator, &.{ num_rois, output_size[0], output_size[1], channels });

        var roi_idx: usize = 0;
        while (roi_idx < num_rois) : (roi_idx += 1) {
            const x1 = try boxes.get(&.{ roi_idx, 0 }) * spatial_scale;
            const y1 = try boxes.get(&.{ roi_idx, 1 }) * spatial_scale;
            const x2 = try boxes.get(&.{ roi_idx, 2 }) * spatial_scale;
            const y2 = try boxes.get(&.{ roi_idx, 3 }) * spatial_scale;

            const roi_width = x2 - x1;
            const roi_height = y2 - y1;

            const bin_size_h = roi_height / @as(f32, @floatFromInt(output_size[0]));
            const bin_size_w = roi_width / @as(f32, @floatFromInt(output_size[1]));

            var ph: usize = 0;
            while (ph < output_size[0]) : (ph += 1) {
                var pw: usize = 0;
                while (pw < output_size[1]) : (pw += 1) {
                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        const hstart = y1 + @as(f32, @floatFromInt(ph)) * bin_size_h;
                        const wstart = x1 + @as(f32, @floatFromInt(pw)) * bin_size_w;

                        const roi_bin_grid_h: usize = if (sampling_ratio > 0) @intCast(sampling_ratio) else @intFromFloat(@ceil(bin_size_h));
                        const roi_bin_grid_w: usize = if (sampling_ratio > 0) @intCast(sampling_ratio) else @intFromFloat(@ceil(bin_size_w));

                        var output_val: f32 = 0.0;
                        var iy: usize = 0;
                        while (iy < roi_bin_grid_h) : (iy += 1) {
                            var ix: usize = 0;
                            while (ix < roi_bin_grid_w) : (ix += 1) {
                                const y = hstart + (@as(f32, @floatFromInt(iy)) + 0.5) * bin_size_h / @as(f32, @floatFromInt(roi_bin_grid_h));
                                const x = wstart + (@as(f32, @floatFromInt(ix)) + 0.5) * bin_size_w / @as(f32, @floatFromInt(roi_bin_grid_w));

                                const y_low: usize = @intFromFloat(@floor(y));
                                const x_low: usize = @intFromFloat(@floor(x));
                                const y_high: usize = y_low + 1;
                                const x_high: usize = x_low + 1;

                                const ly = y - @as(f32, @floatFromInt(y_low));
                                const lx = x - @as(f32, @floatFromInt(x_low));
                                const hy = 1.0 - ly;
                                const hx = 1.0 - lx;

                                var v1: f32 = 0.0;
                                var v2: f32 = 0.0;
                                var v3: f32 = 0.0;
                                var v4: f32 = 0.0;

                                if (y_low < self.shape.dims[1] and x_low < self.shape.dims[2]) {
                                    v1 = try self.get(&.{ 0, y_low, x_low, c });
                                }
                                if (y_low < self.shape.dims[1] and x_high < self.shape.dims[2]) {
                                    v2 = try self.get(&.{ 0, y_low, x_high, c });
                                }
                                if (y_high < self.shape.dims[1] and x_low < self.shape.dims[2]) {
                                    v3 = try self.get(&.{ 0, y_high, x_low, c });
                                }
                                if (y_high < self.shape.dims[1] and x_high < self.shape.dims[2]) {
                                    v4 = try self.get(&.{ 0, y_high, x_high, c });
                                }

                                output_val += hy * hx * v1 + hy * lx * v2 + ly * hx * v3 + ly * lx * v4;
                            }
                        }
                        output_val /= @as(f32, @floatFromInt(roi_bin_grid_h * roi_bin_grid_w));
                        try output.set(&.{ roi_idx, ph, pw, c }, output_val);
                    }
                }
            }
        }

        return output;
    }

    pub fn bilinearInterpolate(self: *const Tensor, allocator: Allocator, output_size: [2]usize, align_corners: bool) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        const out_h = output_size[0];
        const out_w = output_size[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        const h_scale = if (align_corners)
            if (out_h > 1) @as(f32, @floatFromInt(in_h - 1)) / @as(f32, @floatFromInt(out_h - 1)) else 0.0
        else
            @as(f32, @floatFromInt(in_h)) / @as(f32, @floatFromInt(out_h));

        const w_scale = if (align_corners)
            if (out_w > 1) @as(f32, @floatFromInt(in_w - 1)) / @as(f32, @floatFromInt(out_w - 1)) else 0.0
        else
            @as(f32, @floatFromInt(in_w)) / @as(f32, @floatFromInt(out_w));

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    const src_y = if (align_corners) @as(f32, @floatFromInt(oh)) * h_scale else (@as(f32, @floatFromInt(oh)) + 0.5) * h_scale - 0.5;
                    const src_x = if (align_corners) @as(f32, @floatFromInt(ow)) * w_scale else (@as(f32, @floatFromInt(ow)) + 0.5) * w_scale - 0.5;

                    const y0 = @max(0, @as(isize, @intFromFloat(@floor(src_y))));
                    const x0 = @max(0, @as(isize, @intFromFloat(@floor(src_x))));
                    const y1 = @min(@as(isize, @intCast(in_h - 1)), y0 + 1);
                    const x1 = @min(@as(isize, @intCast(in_w - 1)), x0 + 1);

                    const ly = src_y - @as(f32, @floatFromInt(y0));
                    const lx = src_x - @as(f32, @floatFromInt(x0));
                    const hy = 1.0 - ly;
                    const hx = 1.0 - lx;

                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        const v00 = try self.get(&.{ b, @intCast(y0), @intCast(x0), c });
                        const v01 = try self.get(&.{ b, @intCast(y0), @intCast(x1), c });
                        const v10 = try self.get(&.{ b, @intCast(y1), @intCast(x0), c });
                        const v11 = try self.get(&.{ b, @intCast(y1), @intCast(x1), c });

                        const val = v00 * hy * hx + v01 * hy * lx + v10 * ly * hx + v11 * ly * lx;
                        try output.set(&.{ b, oh, ow, c }, val);
                    }
                }
            }
        }

        return output;
    }

    pub fn bicubicInterpolate(self: *const Tensor, allocator: Allocator, output_size: [2]usize) !Tensor {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];
        const channels = self.shape.dims[3];

        const out_h = output_size[0];
        const out_w = output_size[1];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        const h_scale = @as(f32, @floatFromInt(in_h)) / @as(f32, @floatFromInt(out_h));
        const w_scale = @as(f32, @floatFromInt(in_w)) / @as(f32, @floatFromInt(out_w));

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    const src_y = (@as(f32, @floatFromInt(oh)) + 0.5) * h_scale - 0.5;
                    const src_x = (@as(f32, @floatFromInt(ow)) + 0.5) * w_scale - 0.5;

                    const y_int = @as(isize, @intFromFloat(@floor(src_y)));
                    const x_int = @as(isize, @intFromFloat(@floor(src_x)));

                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        var val: f32 = 0.0;
                        var dy: isize = -1;
                        while (dy <= 2) : (dy += 1) {
                            var dx: isize = -1;
                            while (dx <= 2) : (dx += 1) {
                                const y = y_int + dy;
                                const x = x_int + dx;

                                if (y >= 0 and y < @as(isize, @intCast(in_h)) and x >= 0 and x < @as(isize, @intCast(in_w))) {
                                    const coeff_y = cubicWeight(src_y - @as(f32, @floatFromInt(y)));
                                    const coeff_x = cubicWeight(src_x - @as(f32, @floatFromInt(x)));
                                    const pixel = try self.get(&.{ b, @intCast(y), @intCast(x), c });
                                    val += pixel * coeff_y * coeff_x;
                                }
                            }
                        }
                        try output.set(&.{ b, oh, ow, c }, val);
                    }
                }
            }
        }

        return output;
    }

    fn cubicWeight(x: f32) f32 {
        const a: f32 = -0.75;
        const abs_x = @fabs(x);
        if (abs_x <= 1.0) {
            return (a + 2.0) * abs_x * abs_x * abs_x - (a + 3.0) * abs_x * abs_x + 1.0;
        } else if (abs_x < 2.0) {
            return a * abs_x * abs_x * abs_x - 5.0 * a * abs_x * abs_x + 8.0 * a * abs_x - 4.0 * a;
        }
        return 0.0;
    }

    pub fn gridSample(self: *const Tensor, grid: *const Tensor, allocator: Allocator, mode: enum { bilinear, nearest }, padding_mode: enum { zeros, border, reflection }) !Tensor {
        if (self.shape.dims.len != 4 or grid.shape.dims.len != 4) return Error.InvalidShape;
        if (grid.shape.dims[3] != 2) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const channels = self.shape.dims[3];
        const out_h = grid.shape.dims[1];
        const out_w = grid.shape.dims[2];
        const in_h = self.shape.dims[1];
        const in_w = self.shape.dims[2];

        const output = try init(allocator, &.{ batch, out_h, out_w, channels });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var oh: usize = 0;
            while (oh < out_h) : (oh += 1) {
                var ow: usize = 0;
                while (ow < out_w) : (ow += 1) {
                    const grid_x = try grid.get(&.{ b, oh, ow, 0 });
                    const grid_y = try grid.get(&.{ b, oh, ow, 1 });

                    const ix = (grid_x + 1.0) * @as(f32, @floatFromInt(in_w - 1)) / 2.0;
                    const iy = (grid_y + 1.0) * @as(f32, @floatFromInt(in_h - 1)) / 2.0;

                    var c: usize = 0;
                    while (c < channels) : (c += 1) {
                        var val: f32 = 0.0;

                        switch (mode) {
                            .bilinear => {
                                const ix0_f = @floor(ix);
                                const iy0_f = @floor(iy);
                                const ix0 = @as(isize, @intFromFloat(ix0_f));
                                const iy0 = @as(isize, @intFromFloat(iy0_f));
                                const ix1 = ix0 + 1;
                                const iy1 = iy0 + 1;

                                const dx = ix - ix0_f;
                                const dy = iy - iy0_f;

                                var v00: f32 = 0.0;
                                var v01: f32 = 0.0;
                                var v10: f32 = 0.0;
                                var v11: f32 = 0.0;

                                if (applyPaddingMode(iy0, ix0, @intCast(in_h), @intCast(in_w), padding_mode)) |coords| {
                                    v00 = try self.get(&.{ b, coords[0], coords[1], c });
                                }
                                if (applyPaddingMode(iy0, ix1, @intCast(in_h), @intCast(in_w), padding_mode)) |coords| {
                                    v01 = try self.get(&.{ b, coords[0], coords[1], c });
                                }
                                if (applyPaddingMode(iy1, ix0, @intCast(in_h), @intCast(in_w), padding_mode)) |coords| {
                                    v10 = try self.get(&.{ b, coords[0], coords[1], c });
                                }
                                if (applyPaddingMode(iy1, ix1, @intCast(in_h), @intCast(in_w), padding_mode)) |coords| {
                                    v11 = try self.get(&.{ b, coords[0], coords[1], c });
                                }

                                val = v00 * (1.0 - dx) * (1.0 - dy) +
                                      v01 * dx * (1.0 - dy) +
                                      v10 * (1.0 - dx) * dy +
                                      v11 * dx * dy;
                            },
                            .nearest => {
                                const ix_round = @as(isize, @intFromFloat(@round(ix)));
                                const iy_round = @as(isize, @intFromFloat(@round(iy)));

                                if (applyPaddingMode(iy_round, ix_round, @intCast(in_h), @intCast(in_w), padding_mode)) |coords| {
                                    val = try self.get(&.{ b, coords[0], coords[1], c });
                                }
                            },
                        }

                        try output.set(&.{ b, oh, ow, c }, val);
                    }
                }
            }
        }

        return output;
    }

    fn applyPaddingMode(y: isize, x: isize, h: usize, w: usize, mode: enum { zeros, border, reflection }) ?[2]usize {
        var fy = y;
        var fx = x;

        switch (mode) {
            .zeros => {
                if (fy < 0 or fy >= @as(isize, @intCast(h)) or fx < 0 or fx >= @as(isize, @intCast(w))) {
                    return null;
                }
            },
            .border => {
                fy = @max(0, @min(@as(isize, @intCast(h - 1)), fy));
                fx = @max(0, @min(@as(isize, @intCast(w - 1)), fx));
            },
            .reflection => {
                while (fy < 0 or fy >= @as(isize, @intCast(h))) {
                    if (fy < 0) fy = -fy;
                    if (fy >= @as(isize, @intCast(h))) fy = 2 * @as(isize, @intCast(h - 1)) - fy;
                }
                while (fx < 0 or fx >= @as(isize, @intCast(w))) {
                    if (fx < 0) fx = -fx;
                    if (fx >= @as(isize, @intCast(w))) fx = 2 * @as(isize, @intCast(w - 1)) - fx;
                }
            },
        }

        return .{ @intCast(fy), @intCast(fx) };
    }

    pub fn affineGrid(allocator: Allocator, theta: *const Tensor, size: [4]usize) !Tensor {
        if (theta.shape.dims.len != 3) return Error.InvalidShape;
        if (theta.shape.dims[1] != 2 or theta.shape.dims[2] != 3) return Error.InvalidShape;

        const batch = size[0];
        const out_h = size[2];
        const out_w = size[3];

        const grid = try init(allocator, &.{ batch, out_h, out_w, 2 });

        var b: usize = 0;
        while (b < batch) : (b += 1) {
            var h: usize = 0;
            while (h < out_h) : (h += 1) {
                var w: usize = 0;
                while (w < out_w) : (w += 1) {
                    const x = 2.0 * @as(f32, @floatFromInt(w)) / @as(f32, @floatFromInt(out_w - 1)) - 1.0;
                    const y = 2.0 * @as(f32, @floatFromInt(h)) / @as(f32, @floatFromInt(out_h - 1)) - 1.0;

                    const t00 = try theta.get(&.{ b, 0, 0 });
                    const t01 = try theta.get(&.{ b, 0, 1 });
                    const t02 = try theta.get(&.{ b, 0, 2 });
                    const t10 = try theta.get(&.{ b, 1, 0 });
                    const t11 = try theta.get(&.{ b, 1, 1 });
                    const t12 = try theta.get(&.{ b, 1, 2 });

                    const grid_x = t00 * x + t01 * y + t02;
                    const grid_y = t10 * x + t11 * y + t12;

                    try grid.set(&.{ b, h, w, 0 }, grid_x);
                    try grid.set(&.{ b, h, w, 1 }, grid_y);
                }
            }
        }

        return grid;
    }

    pub fn pixelShuffle(self: *Tensor, upscale_factor: usize) !void {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const channels = self.shape.dims[3];
        const height = self.shape.dims[1];
        const width = self.shape.dims[2];

        if (channels % (upscale_factor * upscale_factor) != 0) return Error.InvalidShape;

        const out_channels = channels / (upscale_factor * upscale_factor);
        const out_height = height * upscale_factor;
        const out_width = width * upscale_factor;

        var new_shape = &[_]usize{ batch, out_height, out_width, out_channels };
        try self.reshape(new_shape);
    }

    pub fn pixelUnshuffle(self: *Tensor, downscale_factor: usize) !void {
        if (self.shape.dims.len != 4) return Error.InvalidShape;

        const batch = self.shape.dims[0];
        const height = self.shape.dims[1];
        const width = self.shape.dims[2];
        const channels = self.shape.dims[3];

        if (height % downscale_factor != 0 or width % downscale_factor != 0) return Error.InvalidShape;

        const out_height = height / downscale_factor;
        const out_width = width / downscale_factor;
        const out_channels = channels * downscale_factor * downscale_factor;

        var new_shape = &[_]usize{ batch, out_height, out_width, out_channels };
        try self.reshape(new_shape);
    }

    pub fn embedding(indices: *const Tensor, weight: *const Tensor, allocator: Allocator) !Tensor {
        if (weight.shape.dims.len != 2) return Error.InvalidShape;

        const embedding_dim = weight.shape.dims[1];
        var output_shape = try allocator.alloc(usize, indices.shape.dims.len + 1);
        defer allocator.free(output_shape);

        @memcpy(output_shape[0..indices.shape.dims.len], indices.shape.dims);
        output_shape[indices.shape.dims.len] = embedding_dim;

        const output = try init(allocator, output_shape);

        var idx: usize = 0;
        while (idx < indices.data.len) : (idx += 1) {
            const emb_idx = @as(usize, @intFromFloat(indices.data[idx]));
            if (emb_idx >= weight.shape.dims[0]) return Error.OutOfBounds;

            var e: usize = 0;
            while (e < embedding_dim) : (e += 1) {
                output.data[idx * embedding_dim + e] = try weight.get(&.{ emb_idx, e });
            }
        }

        return output;
    }

    pub fn embeddingBag(indices: *const Tensor, weight: *const Tensor, offsets: *const Tensor, allocator: Allocator, mode: enum { sum, mean, max }) !Tensor {
        if (weight.shape.dims.len != 2 or offsets.shape.dims.len != 1) return Error.InvalidShape;

        const num_bags = offsets.data.len;
        const embedding_dim = weight.shape.dims[1];

        const output = try init(allocator, &.{ num_bags, embedding_dim });

        var bag: usize = 0;
        while (bag < num_bags) : (bag += 1) {
            const offset_start = @as(usize, @intFromFloat(try offsets.get(&.{bag})));
            const offset_end = if (bag + 1 < num_bags)
                @as(usize, @intFromFloat(try offsets.get(&.{bag + 1})))
            else
                indices.data.len;

            var e: usize = 0;
            while (e < embedding_dim) : (e += 1) {
                var result: f32 = switch (mode) {
                    .max => -math.inf(f32),
                    else => 0.0,
                };

                var i = offset_start;
                while (i < offset_end) : (i += 1) {
                    const idx = @as(usize, @intFromFloat(indices.data[i]));
                    const emb_val = try weight.get(&.{ idx, e });

                    switch (mode) {
                        .sum, .mean => result += emb_val,
                        .max => result = @max(result, emb_val),
                    }
                }

                if (mode == .mean and offset_end > offset_start) {
                    result /= @as(f32, @floatFromInt(offset_end - offset_start));
                }

                try output.set(&.{ bag, e }, result);
            }
        }

        return output;
    }

    pub fn cosineEmbeddingLoss(input1: *const Tensor, input2: *const Tensor, target: *const Tensor, margin: f32) !f32 {
        if (input1.data.len != input2.data.len or input1.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < input1.data.len) : (i += 1) {
            const cos_sim = input1.data[i] * input2.data[i];
            const y = target.data[i];

            const loss = if (y == 1.0)
                1.0 - cos_sim
            else
                @max(0.0, cos_sim - margin);

            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(input1.data.len));
    }

    pub fn hingeLoss(pred: *const Tensor, target: *const Tensor, margin: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            const loss = @max(0.0, margin - target.data[i] * pred.data[i]);
            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(pred.data.len));
    }

    pub fn tripletMarginLoss(anchor: *const Tensor, positive: *const Tensor, negative: *const Tensor, margin: f32, p: f32) !f32 {
        if (anchor.data.len != positive.data.len or anchor.data.len != negative.data.len) return Error.ShapeMismatch;

        var dist_pos: f32 = 0.0;
        var dist_neg: f32 = 0.0;

        var i: usize = 0;
        while (i < anchor.data.len) : (i += 1) {
            dist_pos += math.pow(f32, @fabs(anchor.data[i] - positive.data[i]), p);
            dist_neg += math.pow(f32, @fabs(anchor.data[i] - negative.data[i]), p);
        }

        dist_pos = math.pow(f32, dist_pos, 1.0 / p);
        dist_neg = math.pow(f32, dist_neg, 1.0 / p);

        return @max(0.0, dist_pos - dist_neg + margin);
    }

    pub fn kldivLoss(input: *const Tensor, target: *const Tensor, reduction: enum { none, mean, sum }) !f32 {
        if (input.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < input.data.len) : (i += 1) {
            const loss = target.data[i] * (@log(target.data[i]) - input.data[i]);
            total_loss += loss;
        }

        return switch (reduction) {
            .none => total_loss,
            .sum => total_loss,
            .mean => total_loss / @as(f32, @floatFromInt(input.data.len)),
        };
    }

    pub fn bceLoss(pred: *const Tensor, target: *const Tensor, weight: ?*const Tensor) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;
        if (weight != null and weight.?.data.len != pred.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            const p = math.clamp(pred.data[i], 1e-7, 1.0 - 1e-7);
            const loss = -(target.data[i] * @log(p) + (1.0 - target.data[i]) * @log(1.0 - p));

            const w = if (weight) |wt| wt.data[i] else 1.0;
            total_loss += loss * w;
        }

        return total_loss / @as(f32, @floatFromInt(pred.data.len));
    }

    pub fn bceWithLogitsLoss(logits: *const Tensor, target: *const Tensor, pos_weight: ?*const Tensor) !f32 {
        if (logits.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < logits.data.len) : (i += 1) {
            const max_val = @max(0.0, -logits.data[i]);
            const pw = if (pos_weight) |w| w.data[i] else 1.0;

            const loss = (1.0 - target.data[i]) * logits.data[i] + 
                        pw * (max_val + @log(@exp(-max_val) + @exp(-logits.data[i] - max_val)));

            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(logits.data.len));
    }

    pub fn smoothL1Loss(pred: *const Tensor, target: *const Tensor, beta: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            const diff = @fabs(pred.data[i] - target.data[i]);
            const loss = if (diff < beta)
                0.5 * diff * diff / beta
            else
                diff - 0.5 * beta;

            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(pred.data.len));
    }

    pub fn huberLoss(pred: *const Tensor, target: *const Tensor, delta: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            const diff = @fabs(pred.data[i] - target.data[i]);
            const loss = if (diff <= delta)
                0.5 * diff * diff
            else
                delta * (diff - 0.5 * delta);

            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(pred.data.len));
    }

    pub fn quantileLoss(pred: *const Tensor, target: *const Tensor, quantiles: []const f32, allocator: Allocator) ![]f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var losses = try allocator.alloc(f32, quantiles.len);

        for (quantiles, 0..) |q, q_idx| {
            var total_loss: f32 = 0.0;
            var i: usize = 0;
            while (i < pred.data.len) : (i += 1) {
                const diff = target.data[i] - pred.data[i];
                const loss = if (diff > 0.0)
                    q * diff
                else
                    (q - 1.0) * diff;

                total_loss += loss;
            }
            losses[q_idx] = total_loss / @as(f32, @floatFromInt(pred.data.len));
        }

        return losses;
    }

    pub fn poissonNLLLoss(input: *const Tensor, target: *const Tensor, log_input: bool, full: bool) !f32 {
        if (input.data.len != target.data.len) return Error.ShapeMismatch;

        var total_loss: f32 = 0.0;
        var i: usize = 0;
        while (i < input.data.len) : (i += 1) {
            const inp = if (log_input) @exp(input.data[i]) else input.data[i];
            const tgt = target.data[i];

            var loss = inp - tgt * (if (log_input) input.data[i] else @log(inp + 1e-8));

            if (full) {
                loss += tgt * @log(tgt + 1e-8) - tgt + 0.5 * @log(2.0 * math.pi * tgt);
            }

            total_loss += loss;
        }

        return total_loss / @as(f32, @floatFromInt(input.data.len));
    }

    pub fn ctcLoss(log_probs: *const Tensor, targets: *const Tensor, input_lengths: *const Tensor, target_lengths: *const Tensor, blank: usize) !f32 {
        _ = log_probs;
        _ = targets;
        _ = input_lengths;
        _ = target_lengths;
        _ = blank;
        return 0.0;
    }

    pub fn nllLoss(input: *const Tensor, target: *const Tensor, weight: ?*const Tensor, ignore_index: ?usize) !f32 {
        if (input.shape.dims.len < 2) return Error.InvalidShape;

        const batch_size = input.shape.dims[0];
        const num_classes = input.shape.dims[1];

        var total_loss: f32 = 0.0;
        var count: usize = 0;

        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const target_class = @as(usize, @intFromFloat(target.data[b]));

            if (ignore_index) |idx| {
                if (target_class == idx) continue;
            }

            if (target_class >= num_classes) return Error.OutOfBounds;

            const log_prob = try input.get(&.{ b, target_class });
            const w = if (weight) |wt| wt.data[target_class] else 1.0;

            total_loss += -log_prob * w;
            count += 1;
        }

        return if (count > 0) total_loss / @as(f32, @floatFromInt(count)) else 0.0;
    }

    pub fn crossEntropyLoss(logits: *const Tensor, target: *const Tensor, allocator: Allocator, weight: ?*const Tensor) !f32 {
        var log_softmax = try logits.copy(allocator);
        defer log_softmax.deinit();

        try log_softmax.softmax(1);
        for (log_softmax.data) |*val| {
            val.* = @log(val.* + 1e-10);
        }

        return try nllLoss(&log_softmax, target, weight, null);
    }

    pub fn focalLoss(logits: *const Tensor, target: *const Tensor, allocator: Allocator, alpha: f32, gamma: f32) !f32 {
        if (logits.shape.dims.len < 2) return Error.InvalidShape;

        const batch_size = logits.shape.dims[0];
        const num_classes = logits.shape.dims[1];

        var probs = try logits.copy(allocator);
        defer probs.deinit();
        try probs.softmax(1);

        var total_loss: f32 = 0.0;
        var b: usize = 0;
        while (b < batch_size) : (b += 1) {
            const target_class = @as(usize, @intFromFloat(target.data[b]));
            if (target_class >= num_classes) return Error.OutOfBounds;

            const pt = try probs.get(&.{ b, target_class });
            const focal_weight = math.pow(f32, 1.0 - pt, gamma);
            const ce_loss = -@log(pt + 1e-10);

            total_loss += alpha * focal_weight * ce_loss;
        }

        return total_loss / @as(f32, @floatFromInt(batch_size));
    }

    pub fn diceLoss(pred: *const Tensor, target: *const Tensor, smooth: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var intersection: f32 = 0.0;
        var pred_sum: f32 = 0.0;
        var target_sum: f32 = 0.0;

        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            intersection += pred.data[i] * target.data[i];
            pred_sum += pred.data[i];
            target_sum += target.data[i];
        }

        const dice_coeff = (2.0 * intersection + smooth) / (pred_sum + target_sum + smooth);
        return 1.0 - dice_coeff;
    }

    pub fn ioULoss(pred: *const Tensor, target: *const Tensor, smooth: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var intersection: f32 = 0.0;
        var union: f32 = 0.0;

        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            intersection += pred.data[i] * target.data[i];
            union += pred.data[i] + target.data[i] - pred.data[i] * target.data[i];
        }

        const iou = (intersection + smooth) / (union + smooth);
        return 1.0 - iou;
    }

    pub fn tverskyLoss(pred: *const Tensor, target: *const Tensor, alpha: f32, beta: f32, smooth: f32) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var true_pos: f32 = 0.0;
        var false_pos: f32 = 0.0;
        var false_neg: f32 = 0.0;

        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            true_pos += pred.data[i] * target.data[i];
            false_pos += pred.data[i] * (1.0 - target.data[i]);
            false_neg += (1.0 - pred.data[i]) * target.data[i];
        }

        const tversky_index = (true_pos + smooth) / (true_pos + alpha * false_pos + beta * false_neg + smooth);
        return 1.0 - tversky_index;
    }

    pub fn lovaszHingeLoss(pred: *const Tensor, target: *const Tensor, allocator: Allocator) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var errors = try allocator.alloc(f32, pred.data.len);
        defer allocator.free(errors);

        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            const margin = 1.0 - pred.data[i] * (2.0 * target.data[i] - 1.0);
            errors[i] = @max(0.0, margin);
        }

        std.mem.sort(f32, errors, {}, struct {
            pub fn lessThan(_: void, a: f32, b: f32) bool {
                return a > b;
            }
        }.lessThan);

        var total_loss: f32 = 0.0;
        var gts: f32 = 0.0;
        i = 0;
        while (i < errors.len) : (i += 1) {
            gts += target.data[i];
            const grad = @as(f32, @floatFromInt(i + 1)) - gts;
            total_loss += errors[i] * grad;
        }

        return total_loss / @as(f32, @floatFromInt(pred.data.len));
    }

    pub fn wasersteinLoss(pred: *const Tensor, target: *const Tensor) !f32 {
        if (pred.data.len != target.data.len) return Error.ShapeMismatch;

        var total: f32 = 0.0;
        var i: usize = 0;
        while (i < pred.data.len) : (i += 1) {
            total += pred.data[i] * target.data[i];
        }

        return -total / @as(f32, @floatFromInt(pred.data.len));
    }

