test "Batch Normalization" {
    const testing = std.testing;
    const gpa = std.testing.allocator;

    var input = try Tensor.init(gpa, &.{ 2, 4, 4, 3 });
    defer input.deinit();
    var i: usize = 0;
    while (i < input.data.len) : (i += 1) {
        input.data[i] = @as(f32, @floatFromInt(i)) * 0.1;
    }

    var gamma = try Tensor.ones(gpa, &.{3});
    defer gamma.deinit();
    var beta = try Tensor.zeros(gpa, &.{3});
    defer beta.deinit();

    const result = try input.batchNorm(gpa, &gamma, &beta, 1e-5, true);
    defer result.normalized.deinit();
    if (result.mean) |*m| m.deinit();
    if (result.variance) |*v| v.deinit();

    try testing.expect(result.normalized.data.len == input.data.len);
}

